from pathlib import Path

ROOT = Path('.')


def read(path: str) -> str:
    return (ROOT / path).read_text()


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)


def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: expected exactly one match, found {count}: {old[:120]!r}')
    write(path, text.replace(old, new, 1))


# Financial lifecycle actions remain auditable, including fulfillment and user verification.
write(
    'src/app/api/planner/contributions/[id]/actions/route.ts',
    """import { NextRequest, NextResponse } from 'next/server'\nimport { db } from '@/lib/db'\nimport { contributionAvailableAmount, finiteNonNegative } from '@/lib/contributions'\nimport { contributionAllocatedCash, contributionId, getContribution } from '@/lib/contributions/store'\nimport { contextHasPermission, requireWeddingPermission } from '@/lib/wedding-access'\n\ninterface RouteContext { params: Promise<{ id: string }> }\n\nexport async function POST(request: NextRequest, context: RouteContext) {\n  const access = await requireWeddingPermission(request, 'budget.edit')\n  if (access.error) return access.error\n  const { id } = await context.params\n  const weddingId = access.context.weddingId\n  const actorId = access.context.session.userId\n  try {\n    const contribution = await getContribution(weddingId, id)\n    if (!contribution) return NextResponse.json({ success: false, error: 'Contribution not found.' }, { status: 404 })\n    const body = (await request.json()) as Record<string, unknown>\n    const action = String(body.action ?? '')\n\n    if (action === 'allocate') {\n      const budgetItemId = String(body.budgetItemId ?? '')\n      const amount = finiteNonNegative(body.amount)\n      if (!budgetItemId || !amount || amount <= 0) return NextResponse.json({ success: false, error: 'Choose a budget item and amount.' }, { status: 400 })\n      const budget = await db.budgetItem.findFirst({ where: { id: budgetItemId, weddingId }, select: { id: true, currency: true } })\n      if (!budget) return NextResponse.json({ success: false, error: 'Budget item not found for this wedding.' }, { status: 404 })\n      if (budget.currency !== contribution.currency) return NextResponse.json({ success: false, error: 'Allocation currency must match the contribution and budget item.' }, { status: 400 })\n      const allocatedAmount = await contributionAllocatedCash(weddingId, id)\n      const available = contributionAvailableAmount({ type: contribution.type, amount: contribution.amount, fulfillmentState: contribution.fulfillmentState, allocatedAmount })\n      if (amount > available + 0.0001) return NextResponse.json({ success: false, error: `Only ${contribution.currency} ${available.toFixed(2)} is still available to allocate.` }, { status: 409 })\n      await db.$transaction(async (tx) => {\n        await tx.$executeRaw`\n          INSERT INTO wewed_contributions.contribution_allocations\n            (id, wedding_id, contribution_id, budget_item_id, amount, currency, allocation_kind, note, created_by_id)\n          VALUES\n            (${contributionId()}, ${weddingId}, ${id}, ${budgetItemId}, ${amount}, ${contribution.currency}, 'CASH', ${String(body.note ?? '').trim() || null}, ${actorId})\n        `\n        await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution.allocated', actorType: 'user', actorId, targetType: 'WeddingContribution', targetId: id, payload: JSON.stringify({ budgetItemId, amount, currency: contribution.currency }), severity: 'info' } })\n      })\n      return NextResponse.json({ success: true })\n    }\n\n    if (action === 'create-task') {\n      if (!contextHasPermission(access.context, 'planner.edit')) return NextResponse.json({ success: false, error: 'You do not have permission to create Planner tasks.' }, { status: 403 })\n      const title = String(body.title ?? `Follow up contribution from ${contribution.contributorName}`).trim()\n      if (!title) return NextResponse.json({ success: false, error: 'Task title is required.' }, { status: 400 })\n      const task = await db.$transaction(async (tx) => {\n        const created = await tx.plannerTask.create({ data: { weddingId, title, description: String(body.description ?? contribution.title).trim() || null, category: 'other', status: 'todo', priority: 'medium', dueDate: body.dueDate ? new Date(String(body.dueDate)) : null, assigneeUserId: actorId } })\n        await tx.$executeRaw`\n          INSERT INTO wewed_contributions.task_links\n            (id, wedding_id, contribution_id, planner_task_id, link_role)\n          VALUES\n            (${contributionId()}, ${weddingId}, ${id}, ${created.id}, ${String(body.linkRole ?? 'follow_up')})\n        `\n        await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution.task_linked', actorType: 'user', actorId, targetType: 'WeddingContribution', targetId: id, payload: JSON.stringify({ plannerTaskId: created.id }), severity: 'info' } })\n        return created\n      })\n      return NextResponse.json({ success: true, data: task })\n    }\n\n    if (action === 'mark-thanked') {\n      await db.$transaction(async (tx) => {\n        await tx.$executeRaw`UPDATE wewed_contributions.wedding_contributions SET thank_you_state = 'SENT', updated_at = NOW() WHERE id = ${id} AND wedding_id = ${weddingId}`\n        await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution.thanked', actorType: 'user', actorId, targetType: 'WeddingContribution', targetId: id, severity: 'info' } })\n      })\n      return NextResponse.json({ success: true })\n    }\n\n    if (action === 'mark-received') {\n      if (contribution.fulfillmentState !== 'PENDING') return NextResponse.json({ success: false, error: 'Only pending contributions can be marked received from this action.' }, { status: 409 })\n      const nextState = ['GOODS_IN_KIND','SERVICE_IN_KIND','TIME_LABOUR','DISCOUNT_SPONSORSHIP'].includes(contribution.type) ? 'DELIVERED' : contribution.type === 'DIRECT_VENDOR_PAYMENT' ? 'PAID_DIRECT' : 'RECEIVED'\n      if (nextState === 'PAID_DIRECT') return NextResponse.json({ success: false, error: 'Direct vendor payments need a service engagement and payment record. Edit through the direct-payment flow instead.' }, { status: 409 })\n      await db.$transaction(async (tx) => {\n        await tx.$executeRaw`UPDATE wewed_contributions.wedding_contributions SET fulfillment_state = ${nextState}, commitment_state = 'CONFIRMED', thank_you_state = 'TO_THANK', fulfilled_at = NOW(), updated_at = NOW() WHERE id = ${id} AND wedding_id = ${weddingId}`\n        await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution.fulfilled', actorType: 'user', actorId, targetType: 'WeddingContribution', targetId: id, payload: JSON.stringify({ fulfillmentState: nextState }), severity: 'info' } })\n      })\n      return NextResponse.json({ success: true })\n    }\n\n    if (action === 'mark-verified') {\n      if (!['RECEIVED','DELIVERED','PAID_DIRECT','COMPLETED'].includes(contribution.fulfillmentState)) return NextResponse.json({ success: false, error: 'Verify a contribution after it has been received, delivered or paid.' }, { status: 409 })\n      if (contribution.verificationState === 'RECONCILED') return NextResponse.json({ success: true })\n      await db.$transaction(async (tx) => {\n        await tx.$executeRaw`UPDATE wewed_contributions.wedding_contributions SET verification_state = 'CONFIRMED_BY_USER', updated_at = NOW() WHERE id = ${id} AND wedding_id = ${weddingId}`\n        await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution.verified', actorType: 'user', actorId, targetType: 'WeddingContribution', targetId: id, severity: 'info' } })\n      })\n      return NextResponse.json({ success: true })\n    }\n\n    return NextResponse.json({ success: false, error: 'Unsupported contribution action.' }, { status: 400 })\n  } catch (error) {\n    console.error('[CONTRIBUTION ACTION] error', error)\n    return NextResponse.json({ success: false, error: 'Could not complete the contribution action.' }, { status: 500 })\n  }\n}\n""",
)

# Public campaign governance changes are audit facts because they alter what guests can see.
write(
    'src/app/api/planner/contribution-campaigns/route.ts',
    """import { NextRequest, NextResponse } from 'next/server'\nimport { db } from '@/lib/db'\nimport { contributionId, listCampaigns } from '@/lib/contributions/store'\nimport { finiteNonNegative, normalizeContributionCampaignType, normalizeCurrency } from '@/lib/contributions'\nimport { requireWeddingPermission } from '@/lib/wedding-access'\n\nexport async function GET(request: NextRequest) {\n  const access = await requireWeddingPermission(request, 'budget.view')\n  if (access.error) return access.error\n  try {\n    return NextResponse.json({ success: true, data: await listCampaigns(access.context.weddingId) })\n  } catch (error) {\n    console.error('[CONTRIBUTION CAMPAIGNS GET] error', error)\n    return NextResponse.json({ success: false, error: 'Could not load contribution campaigns.' }, { status: 500 })\n  }\n}\n\nexport async function POST(request: NextRequest) {\n  const access = await requireWeddingPermission(request, 'budget.edit')\n  if (access.error) return access.error\n  const weddingId = access.context.weddingId\n  const actorId = access.context.session.userId\n  try {\n    const body = (await request.json()) as Record<string, unknown>\n    const title = String(body.title ?? '').trim()\n    if (!title) return NextResponse.json({ success: false, error: 'Campaign title is required.' }, { status: 400 })\n    const type = normalizeContributionCampaignType(body.type ?? 'HONEYMOON')\n    if (!type) return NextResponse.json({ success: false, error: 'Choose a valid contribution campaign type.' }, { status: 400 })\n    const externalUrl = String(body.externalUrl ?? '').trim() || null\n    if (externalUrl && !/^https:\/\//i.test(externalUrl)) return NextResponse.json({ success: false, error: 'External campaign links must use HTTPS.' }, { status: 400 })\n    const id = contributionId()\n    const currency = normalizeCurrency(body.currency)\n    await db.$transaction(async (tx) => {\n      await tx.$executeRaw`\n        INSERT INTO wewed_contributions.campaigns\n          (id, wedding_id, type, title, description, target_amount, currency, published, show_target, show_raised, external_url, cta_label, invitation_visible, public_note)\n        VALUES\n          (${id}, ${weddingId}, ${type}, ${title}, ${String(body.description ?? '').trim() || null}, ${finiteNonNegative(body.targetAmount)}, ${currency}, ${Boolean(body.published)}, ${Boolean(body.showTarget)}, ${Boolean(body.showRaised)}, ${externalUrl}, ${String(body.ctaLabel ?? '').trim() || null}, ${Boolean(body.invitationVisible)}, ${String(body.publicNote ?? '').trim() || null})\n      `\n      await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution_campaign.created', actorType: 'user', actorId, targetType: 'ContributionCampaign', targetId: id, payload: JSON.stringify({ type, published: Boolean(body.published), invitationVisible: Boolean(body.invitationVisible), currency }), severity: 'info' } })\n    })\n    const row = (await listCampaigns(weddingId)).find((item) => item.id === id)\n    return NextResponse.json({ success: true, data: row ?? null }, { status: 201 })\n  } catch (error) {\n    console.error('[CONTRIBUTION CAMPAIGNS POST] error', error)\n    return NextResponse.json({ success: false, error: 'Could not create the campaign.' }, { status: 500 })\n  }\n}\n""",
)

write(
    'src/app/api/planner/contribution-campaigns/[id]/route.ts',
    """import { NextRequest, NextResponse } from 'next/server'\nimport { db } from '@/lib/db'\nimport { finiteNonNegative, normalizeCurrency } from '@/lib/contributions'\nimport { requireWeddingPermission } from '@/lib/wedding-access'\n\ninterface RouteContext { params: Promise<{ id: string }> }\n\nexport async function PATCH(request: NextRequest, context: RouteContext) {\n  const access = await requireWeddingPermission(request, 'budget.edit')\n  if (access.error) return access.error\n  const { id } = await context.params\n  const weddingId = access.context.weddingId\n  const actorId = access.context.session.userId\n  try {\n    const rows = await db.$queryRaw<Array<{ id: string }>>`SELECT id FROM wewed_contributions.campaigns WHERE id = ${id} AND wedding_id = ${weddingId} LIMIT 1`\n    if (!rows[0]) return NextResponse.json({ success: false, error: 'Campaign not found.' }, { status: 404 })\n    const body = (await request.json()) as Record<string, unknown>\n    const title = typeof body.title === 'string' ? body.title.trim() : null\n    const description = typeof body.description === 'string' ? body.description.trim() || null : null\n    const publicNote = typeof body.publicNote === 'string' ? body.publicNote.trim() || null : null\n    const ctaLabel = typeof body.ctaLabel === 'string' ? body.ctaLabel.trim() || null : null\n    const externalUrl = body.externalUrl === undefined ? null : String(body.externalUrl ?? '').trim() || null\n    if (externalUrl && !/^https:\/\//i.test(externalUrl)) return NextResponse.json({ success: false, error: 'External campaign links must use HTTPS.' }, { status: 400 })\n    const targetAmount = body.targetAmount === undefined ? null : finiteNonNegative(body.targetAmount)\n    const currency = body.currency === undefined ? null : normalizeCurrency(body.currency)\n    const published = typeof body.published === 'boolean' ? body.published : null\n    const showTarget = typeof body.showTarget === 'boolean' ? body.showTarget : null\n    const showRaised = typeof body.showRaised === 'boolean' ? body.showRaised : null\n    const invitationVisible = typeof body.invitationVisible === 'boolean' ? body.invitationVisible : null\n    await db.$transaction(async (tx) => {\n      await tx.$executeRaw`\n        UPDATE wewed_contributions.campaigns\n           SET title = COALESCE(${title}, title),\n               description = CASE WHEN ${body.description !== undefined} THEN ${description} ELSE description END,\n               public_note = CASE WHEN ${body.publicNote !== undefined} THEN ${publicNote} ELSE public_note END,\n               cta_label = CASE WHEN ${body.ctaLabel !== undefined} THEN ${ctaLabel} ELSE cta_label END,\n               external_url = CASE WHEN ${body.externalUrl !== undefined} THEN ${externalUrl} ELSE external_url END,\n               target_amount = CASE WHEN ${body.targetAmount !== undefined} THEN ${targetAmount} ELSE target_amount END,\n               currency = COALESCE(${currency}, currency),\n               published = COALESCE(${published}, published),\n               show_target = COALESCE(${showTarget}, show_target),\n               show_raised = COALESCE(${showRaised}, show_raised),\n               invitation_visible = COALESCE(${invitationVisible}, invitation_visible),\n               updated_at = NOW()\n         WHERE id = ${id} AND wedding_id = ${weddingId}\n      `\n      await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution_campaign.updated', actorType: 'user', actorId, targetType: 'ContributionCampaign', targetId: id, payload: JSON.stringify({ fields: Object.keys(body) }), severity: 'info' } })\n    })\n    return NextResponse.json({ success: true })\n  } catch (error) {\n    console.error('[CONTRIBUTION CAMPAIGN PATCH] error', error)\n    return NextResponse.json({ success: false, error: 'Could not update campaign.' }, { status: 500 })\n  }\n}\n\nexport async function DELETE(request: NextRequest, context: RouteContext) {\n  const access = await requireWeddingPermission(request, 'budget.edit')\n  if (access.error) return access.error\n  const { id } = await context.params\n  const weddingId = access.context.weddingId\n  const actorId = access.context.session.userId\n  try {\n    const rows = await db.$queryRaw<Array<{ count: bigint }>>`SELECT COUNT(*) AS count FROM wewed_contributions.wedding_contributions WHERE wedding_id = ${weddingId} AND campaign_id = ${id}`\n    if (Number(rows[0]?.count ?? 0) > 0) return NextResponse.json({ success: false, error: 'Campaigns with recorded contributions should be unpublished rather than deleted.' }, { status: 409 })\n    await db.$transaction(async (tx) => {\n      const deleted = await tx.$executeRaw`DELETE FROM wewed_contributions.campaigns WHERE id = ${id} AND wedding_id = ${weddingId}`\n      if (deleted > 0) await tx.auditEvent.create({ data: { weddingId, eventType: 'contribution_campaign.deleted_empty', actorType: 'user', actorId, targetType: 'ContributionCampaign', targetId: id, severity: 'warning' } })\n    })\n    return NextResponse.json({ success: true })\n  } catch (error) {\n    console.error('[CONTRIBUTION CAMPAIGN DELETE] error', error)\n    return NextResponse.json({ success: false, error: 'Could not delete campaign.' }, { status: 500 })\n  }\n}\n""",
)

